"172 :     private void visitScript(NodeTraversal t, Node script) {
173 :       Preconditions.checkArgument(scriptNodeCount == 1,
174 :           "ProcessCommonJSModules supports only one invocation per " +
175 :           "CompilerInput / script node");
176 :       String moduleName = guessCJSModuleName(normalizeSourceName(script
177 :           .getSourceFileName()));
178 :       script.addChildToFront(IR.var(IR.name(moduleName), IR.objectlit())
179 :           .copyInformationFromForTree(script));
180 :       if (reportDependencies) {
181 :         CompilerInput ci = t.getInput();
182 :         ci.addProvide(moduleName);
183 :         JSModule m = new JSModule(moduleName);
184 :         m.addAndOverrideModule(ci);
185 :         module = m;
186 :       }
187 :       script.addChildToFront(IR.exprResult(
188 :           IR.call(IR.getprop(IR.name("goog"), IR.string("provide")),
189 :               IR.string(moduleName))).copyInformationFromForTree(script));
190 : 
191 :       emitOptionalModuleExportsOverride(script, moduleName);
192 : 
193 :       // Rename vars to not conflict in global scope.
194 :       NodeTraversal.traverse(compiler, script, new SuffixVarsCallback(
195 :           moduleName));
196 : 
197 :       compiler.reportCodeChange();
198 :     }"

